LOAD spatial;

-- Find where each ferry route crosses the shipping lane.
-- Return: route_name, crossing_point (WKT text) ordered by route_name

setup:
CREATE TABLE ferry_routes AS SELECT * FROM (VALUES
  ('Harbor Express', ST_GeomFromText('LINESTRING(0 0, 10 10)')),
  ('Island Hopper',  ST_GeomFromText('LINESTRING(0 10, 10 0)')),
  ('Coastal Loop',   ST_GeomFromText('LINESTRING(0 20, 10 20)'))
) t(route_name, geom);

CREATE TABLE shipping_lane AS SELECT * FROM (VALUES
  (ST_GeomFromText('LINESTRING(5 -5, 5 25)'))
) t(geom);

solution:
LOAD spatial;

SELECT f.route_name,
       ST_AsText(ST_Intersection(f.geom, s.geom)) AS crossing_point
FROM ferry_routes f
JOIN shipping_lane s ON ST_Intersects(f.geom, s.geom)
ORDER BY f.route_name;
